import {parseDataModule,MAX_MODULE_BYTES,selectedSources,verifyModuleSource} from './data-module.js';
import {digest} from './core.js';
const $=id=>document.getElementById(id);let loaded=null,manifestBytes=null,index=0,files=new Map(),single=null,epoch=0,pending=null;
const say=text=>{$('module-status').textContent=text;};
function render(){for(const id of ['module-manifest','module-folder','module-single'])$(id).disabled=!!pending;if(!loaded)return;$('module-task').hidden=false;const item=loaded.items[index];$('module-title').textContent=loaded.title;$('module-position').textContent='Item '+(index+1)+' of '+loaded.items.length;$('module-item-title').textContent=item.title;$('module-question').textContent=item.question;$('module-baseline').textContent=item.baseline?'Supplied '+({'source-text':'source passage','supplied-machine':'machine reading',claim:'reading or claim'}[item.baselineKind])+' (unverified):\n'+item.baseline:'No baseline supplied. Enter the passage or claim yourself.';$('module-source').textContent='Source: '+item.source.path+' · '+(item.source.bytes??'size unknown')+' bytes · expected SHA-256 '+(item.source.sha256||'not supplied; source identity unverified');$('module-rights').textContent='Declared reuse basis (not verified): '+loaded.reuseStatement;$('module-external').replaceChildren();if(item.source.url){const a=document.createElement('a');a.href=item.source.url;a.target='_blank';a.rel='noopener noreferrer';a.textContent='Open unverified external source reference';$('module-external').append(a);}$('module-previous').disabled=!!pending||index===0;$('module-next').disabled=!!pending||index+1===loaded.items.length;$('module-review').disabled=!!pending||!(single||files.get(item.source.path));}
$('module-manifest').onchange=async event=>{const file=event.target.files[0];if(!file)return;const ticket=++epoch;try{if(file.size>MAX_MODULE_BYTES)throw Error('Manifest exceeds 1 MiB');const bytes=await file.arrayBuffer(),next=parseDataModule(new TextDecoder('utf-8',{fatal:true}).decode(bytes));if(ticket!==epoch)return;loaded=next;manifestBytes=bytes;index=0;single=null;files=new Map();$('module-folder').value='';$('module-single').value='';say(next.items.length+' tasks loaded. Select the source folder or this item’s file. No source host contacted.');render();}catch(e){if(ticket===epoch)say(e.message+' Previous queue retained.');}finally{event.target.value='';}};
$('module-folder').onchange=e=>{try{files=selectedSources([...e.target.files]);single=null;$('module-single').value='';say(files.size+' selected files indexed by relative path; source bytes will be checked per item.');render();}catch(error){say(error.message+' Previous file selection retained.');}e.target.value='';};
$('module-single').onchange=e=>{single=e.target.files[0]||single;say(single?'One selected source is ready for byte verification.':'Choose a source file.');render();e.target.value='';};
function move(delta){if(pending)return;index=Math.max(0,Math.min(loaded.items.length-1,index+delta));single=null;$('module-single').value='';render();}
$('module-previous').onclick=()=>move(-1);$('module-next').onclick=()=>move(1);
$('module-review').onclick=async()=>{if(!loaded||pending)return;const moduleAtStart=loaded,item=loaded.items[index],file=single||files.get(item.source.path),version=epoch,raw=manifestBytes;let win=null,channel=null,timer=null;pending={};say('Checking the selected source…');render();
 try{
  if(typeof BroadcastChannel==='undefined')throw Error('This browser cannot hand off a module file; choose it directly in Reckoner.');
  win=window.open('about:blank','_blank');if(!win)throw Error('The browser blocked the review tab. Allow this local action, then try again.');win.document.body.textContent='Checking the selected source before opening Reckoner…';
  const verified=await verifyModuleSource(item,file,digest);if(loaded!==moduleAtStart||epoch!==version)throw Error('Module changed while the source was checked.');
  const ticket=crypto.randomUUID(),u=new URL('index.html',location.href);const workspace=crypto.randomUUID();u.searchParams.set('workspace',workspace);u.searchParams.set('moduleTicket',ticket);channel=new BroadcastChannel('reckoner-module:'+ticket);
  let finished=false;const finish=()=>{if(finished)return;finished=true;clearTimeout(timer);channel?.close();pending=null;render();};let delivered=false;
  channel.onmessage=e=>{if(finished||e.data?.ticket!==ticket)return;if(e.data.type==='request'&&!delivered){delivered=true;channel.postMessage({type:'source',ticket,manifestBytes:raw,taskId:item.id,file:new File([verified.buffer],file.name,{type:verified.mime})});}else if(e.data.type==='accepted'){say('Source checked and task opened in its separate workspace. Review and save there.');finish();}else if(e.data.type==='refused'){say('Task not applied: '+e.data.message);finish();}};
  win.location.replace(u.href);
  timer=setTimeout(()=>{if(finished)return;say('No review acknowledgement. The new tab may be loading or may already contain work; check it before retrying.');finish();},22000);
 }catch(error){try{if(win&&!win.closed&&win.location.href==='about:blank')win.close();}catch{/* A user may have navigated the placeholder across origins. */}finally{channel?.close();clearTimeout(timer);pending=null;say(error.message+' Existing review work is unchanged.');render();}}
};
